<script lang="ts">
	import { api } from '$lib/api';
	let productName = $state(''); let supportUrl = $state(''); let announcement = $state(''); let loading = $state(true); let error = $state(''); let saved = $state(false);
	$effect(() => { (async () => { try { const result = await api<{ settings: Record<string, unknown> }>('/api/admin/settings'); productName = typeof result.settings.productName === 'string' ? result.settings.productName : ''; supportUrl = typeof result.settings.supportUrl === 'string' ? result.settings.supportUrl : ''; announcement = typeof result.settings.announcement === 'string' ? result.settings.announcement : ''; } catch (cause) { error = cause instanceof Error ? cause.message : 'Unable to load settings'; } finally { loading = false; } })(); });
	async function save() { loading = true; error = ''; saved = false; try { await api('/api/admin/settings', { method: 'PATCH', body: { productName: productName.trim() || null, supportUrl: supportUrl.trim() || null, announcement: announcement.trim() || null } }); saved = true; } catch (cause) { error = cause instanceof Error ? cause.message : 'Unable to save settings'; } finally { loading = false; } }
</script>
<div><h2 class="text-2xl">Settings</h2><p class="mb-5 mt-1 text-sm text-text-secondary">Edit server-managed product presentation.</p><form onsubmit={(event) => { event.preventDefault(); save(); }} class="max-w-2xl space-y-4"><label class="block text-sm text-text-secondary">Product name<input bind:value={productName} maxlength="500" class="mt-1 w-full rounded-lg border border-border bg-surface px-3 py-2" /></label><label class="block text-sm text-text-secondary">Support URL<input bind:value={supportUrl} type="url" maxlength="500" placeholder="https://support.example.test" class="mt-1 w-full rounded-lg border border-border bg-surface px-3 py-2" /></label><label class="block text-sm text-text-secondary">Announcement<textarea bind:value={announcement} maxlength="500" rows="5" class="mt-1 w-full rounded-lg border border-border bg-surface px-3 py-2"></textarea><span class="text-xs text-text-muted">{announcement.length}/500</span></label>{#if error}<p class="text-sm text-lag-danger">{error}</p>{/if}<div class="flex items-center justify-end gap-3">{#if saved}<span class="text-sm text-lag-success">Saved</span>{/if}<button disabled={loading} class="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{loading ? 'Saving...' : 'Save settings'}</button></div></form></div>
